INSERT INTO engineering_change_orders (eco_number, eco_title, eco_description, eco_status, part_number, current_revision, new_revision, affected_bom_level, change_type, change_detail, change_drafter, change_approver, drafted_date, approved_date, implemented_date, new_status) VALUES ('ECO-0001', 'Top Tube Material Upgrade for Weight Reduction', 'Replace Top Tube material from Al 6061-T6 to Al 7075-T6 to reduce frame weight by 120g while maintaining yield strength above 450 MPa. Requires updated weld procedure.', 'APPROVED', 'FRM-003', 'F', 'G', 3, 'MATERIAL_CHANGE', 'Aluminum alloy: 6061-T6 -> 7075-T6; Wall thickness: 1.2 mm -> 1.0 mm; Weight savings: 120 g', 3, 1, '2025-08-15', '2025-09-10', '2025-11-01', 'RELEASED');
INSERT INTO engineering_change_orders (eco_number, eco_title, eco_description, eco_status, part_number, current_revision, new_revision, affected_bom_level, change_type, change_detail, change_drafter, change_approver, drafted_date, approved_date, implemented_date, new_status) VALUES ('ECO-0002', 'Rear Dropouts Forged-to-CNC Conversion', 'Replace steel forged rear dropouts with CNC-machined 7075 aluminum dropouts to save 45g per dropout. Increased dimensional accuracy for better wheel alignment.', 'APPROVED', 'FRM-010', 'M', 'N', 2, 'MATERIAL_CHANGE', 'Process: forged steel -> CNC 7075 Al; Weight: 28g -> 12g each; Tolerance: ±0.3 mm -> ±0.05 mm', 2, 1, '2025-11-20', '2026-01-08', '2026-03-01', 'RELEASED');
INSERT INTO engineering_change_orders (eco_number, eco_title, eco_description, eco_status, part_number, current_revision, new_revision, affected_bom_level, change_type, change_detail, change_drafter, change_approver, drafted_date, approved_date, implemented_date, new_status) VALUES ('ECO-0003', 'Chain Upgrade to Corrosion-Resistant Variant', 'Replace KMC Z50 chain with KMC Z51 nickel-plated variant for improved corrosion resistance in wet-weather markets. Backward compatible with existing drivetrain.', 'REVIEW', 'DRV-009', 'H', 'I', 2, 'SUPPLIER_CHANGE', 'Model: KMC Z50 -> KMC Z51; Coating: unplated -> nickel-plated; Salt spray: 24 hr -> 72 hr; Cost increase: +$0.45/unit', 1, 5, '2026-02-10', NULL, NULL, 'RELEASED');
INSERT INTO engineering_change_orders (eco_number, eco_title, eco_description, eco_status, part_number, current_revision, new_revision, affected_bom_level, change_type, change_detail, change_drafter, change_approver, drafted_date, approved_date, implemented_date, new_status) VALUES ('ECO-0004', 'Add Puncture Protection to Front Inner Tube', 'Add Slime-brand puncture sealant inside front inner tube to reduce flat tire incidence by estimated 60%. Increases tubewall thickness by 0.3 mm.', 'DRAFT', 'WHL-007', 'L', 'M', 2, 'MATERIAL_CHANGE', 'Tube: standard butyl -> Slime-filled butyl; Wall: 1.0 mm -> 1.3 mm; Weight: 140 g -> 165 g; Target flat rate: 4.2% -> 1.7%', 1, NULL, '2026-03-22', NULL, NULL, 'RELEASED');
INSERT INTO engineering_change_orders (eco_number, eco_title, eco_description, eco_status, part_number, current_revision, new_revision, affected_bom_level, change_type, change_detail, change_drafter, change_approver, drafted_date, approved_date, implemented_date, new_status) VALUES ('ECO-0005', 'Front Brake Pad Compound Upgrade to Ceramic', 'Replace OEM rubber brake pads with ceramic compound pads for improved wet-weather braking performance and reduced rim wear. Increase pad service life by ~40%.', 'APPROVED', 'BRK-004', 'B', 'C', 2, 'MATERIAL_CHANGE', 'Pad compound: standard rubber -> ceramic-infused rubber; Wet braking coeff: 0.28 -> 0.38; Rim wear rate: 0.12mm/1000km -> 0.07mm/1000km', 4, 2, '2025-10-05', '2025-11-15', '2026-02-01', 'RELEASED');
INSERT INTO engineering_change_orders (eco_number, eco_title, eco_description, eco_status, part_number, current_revision, new_revision, affected_bom_level, change_type, change_detail, change_drafter, change_approver, drafted_date, approved_date, implemented_date, new_status) VALUES ('ECO-0006', 'Switch to Lock-On Ergonomic Grips', 'Replace standard slip-on rubber grips with lock-on ergonomic grips with aluminum clamp collars. Eliminates grip rotation under heavy use and improves rider comfort.', 'REVIEW', 'CPT-005', 'D', 'E', 2, 'DESIGN_CHANGE', 'Type: slip-on rubber -> lock-on ergonomic; Collar: none -> CNC Al 6061; OD: 30 mm -> 32 mm (tapered); Length: 130 mm -> 135 mm', 3, 1, '2026-01-14', NULL, NULL, 'RELEASED');
INSERT INTO engineering_change_orders (eco_number, eco_title, eco_description, eco_status, part_number, current_revision, new_revision, affected_bom_level, change_type, change_detail, change_drafter, change_approver, drafted_date, approved_date, implemented_date, new_status) VALUES ('ECO-0007', 'Pedal Upgrade from Nylon to Aluminum Platform', 'Replace nylon composite pedals with CNC aluminum platform pedals for increased durability and better grip. Include replaceable steel pins.', 'DRAFT', 'PED-001', 'Y', 'Z', 1, 'MATERIAL_CHANGE', 'Body: nylon composite -> Al 6061-T6 CNC; Pins: molded plastic -> M3 steel replaceable (8 per pedal); Bearing: loose ball -> sealed cartridge; Weight: 310g -> 380g', 5, NULL, '2026-04-05', NULL, NULL, 'RELEASED');
INSERT INTO engineering_change_orders (eco_number, eco_title, eco_description, eco_status, part_number, current_revision, new_revision, affected_bom_level, change_type, change_detail, change_drafter, change_approver, drafted_date, approved_date, implemented_date, new_status) VALUES ('ECO-0008', 'Steerer Tube Wall Thickness Increase for Safety Margin', 'Increase steerer tube wall thickness from 1.2 mm to 1.5 mm to address fatigue test failures at 200k cycles under 180 kg rider load. Reduce ID from 22.2 mm to 21.6 mm.', 'APPROVED', 'FORK-003', 'R', 'S', 2, 'DIMENSION_CHANGE', 'Wall thickness: 1.2 mm -> 1.5 mm; ID: 22.2 mm -> 21.6 mm; Fatigue life: 180k cycles -> 350k cycles; Weight increase: +18 g', 4, 2, '2025-06-20', '2025-08-01', '2025-10-15', 'RELEASED');
INSERT INTO engineering_change_orders (eco_number, eco_title, eco_description, eco_status, part_number, current_revision, new_revision, affected_bom_level, change_type, change_detail, change_drafter, change_approver, drafted_date, approved_date, implemented_date, new_status) VALUES ('ECO-0009', 'Seatpost Offset Head for Improved Saddle Adjustment', 'Add 20 mm offset head to seatpost to provide increased saddle fore-aft adjustment range. Compatible with existing 27.2 mm seat tube and saddle rail clamp.', 'REVIEW', 'SET-003', 'Z', 'AA', 2, 'DESIGN_CHANGE', 'Head: straight (0 mm offset) -> offset (20 mm set-back); Clamp: 2-bolt side clamp -> 2-bolt hidden; Weight: 285 g -> 315 g; Rail compatibility: 7 mm round -> 7 mm round/oval', 2, 4, '2025-12-01', NULL, NULL, 'RELEASED');
INSERT INTO engineering_change_orders (eco_number, eco_title, eco_description, eco_status, part_number, current_revision, new_revision, affected_bom_level, change_type, change_detail, change_drafter, change_approver, drafted_date, approved_date, implemented_date, new_status) VALUES ('ECO-0010', 'Cog 18T Surface Hardening for Extended Wear Life', 'Change 18T cassette cog from nickel-plated steel to induction-hardened chromoly steel to extend service life by 300% in high-torque gear position.', 'APPROVED', 'CST-003', 'F', 'G', 3, 'MATERIAL_CHANGE', 'Material: nickel-plated steel -> induction-hardened 4130 CrMo; Hardness: 35 HRC surface -> 58 HRC surface; Wear life: 8000 km -> 24000 km; Cost: +$0.18/unit', 1, 3, '2025-05-10', '2025-06-20', '2025-08-01', 'RELEASED');
